            break

    if len(looking_away_giraffes) != 3:
        return image_patch

    # Find the giraffe to the right of these three giraffes
    rightmost_giraffe = max(looking_away_giraffes, key=lambda g: g.horizontal_center)

    return rightmost_giraffe

